changeSet.sql:
CREATE TABLE IF NOT EXISTS app.company ( delete_flag INTEGER DEFAULT 0, company_id BIGSERIAL NOT NULL, company_name VARCHAR(100) NOT NULL, company_address VARCHAR(255), company_email_id VARCHAR(50) NOT NULL, max_users INTEGER, created_by BIGINT, created_date_time TIMESTAMPTZ(6), updated_by BIGINT, updated_date_time TIMESTAMPTZ(6), CONSTRAINT company_pkey PRIMARY KEY (company_id), CONSTRAINT company_email_id_key UNIQUE (company_email_id) );
CREATE TABLE IF NOT EXISTS app.user_role ( delete_flag INTEGER DEFAULT 0, role_id BIGSERIAL NOT NULL PRIMARY KEY, role_name VARCHAR(255), created_by VARCHAR(255), created_date_time TIMESTAMPTZ(6), updated_by VARCHAR(255), updated_date_time TIMESTAMPTZ(6) );
ALTER TABLE app.app_user ADD COLUMN company_id BIGINT NOT NULL, ADD COLUMN role_id BIGINT NOT NULL, ADD CONSTRAINT app_user_company_id_fkey FOREIGN KEY (company_id) REFERENCES app.company (company_id) ON DELETE CASCADE, ADD CONSTRAINT app_user_role_id_fkey FOREIGN KEY (role_id) REFERENCES app.user_role (role_id) ON DELETE CASCADE;
ALTER TABLE app.vendor ADD COLUMN company_id BIGINT NOT NULL, ADD CONSTRAINT vendor_company_id_fkey FOREIGN KEY (company_id) REFERENCES app.company (company_id) ON DELETE CASCADE;
ALTER TABLE app.part ADD COLUMN company_id BIGINT NOT NULL, ADD CONSTRAINT part_company_id_fkey FOREIGN KEY (company_id) REFERENCES app.company (company_id) ON DELETE CASCADE;
ALTER TABLE app.part_cost ADD COLUMN company_id BIGINT NOT NULL, ADD CONSTRAINT part_company_id_fkey FOREIGN KEY (company_id) REFERENCES app.company(company_id) ON DELETE CASCADE;
ALTER TABLE app.part_category ADD COLUMN company_id BIGINT NOT NULL, ADD CONSTRAINT part_company_id_fkey FOREIGN KEY (company_id) REFERENCES app.company(company_id) ON DELETE CASCADE;
ALTER TABLE app.cost_factor ADD COLUMN company_id BIGINT NOT NULL, ADD CONSTRAINT part_company_id_fkey FOREIGN KEY (company_id) REFERENCES app.company(company_id) ON DELETE CASCADE;
ALTER TABLE app.part_unit ADD COLUMN company_id BIGINT NOT NULL, ADD CONSTRAINT part_company_id_fkey FOREIGN KEY (company_id) REFERENCES app.company(company_id) ON DELETE CASCADE;

rollback.sql:
DROP TABLE app.company CASCADE;
DROP TABLE app.user_role CASCADE;
ALTER TABLE app.app_user 
DROP COLUMN company_id CASCADE, 
DROP COLUMN role_id CASCADE;
ALTER TABLE app.vendor DROP COLUMN company_id CASCADE;
ALTER TABLE app.part DROP COLUMN company_id CASCADE;
ALTER TABLE app.part_cost DROP COLUMN company_id CASCADE;
ALTER TABLE app.part_category DROP COLUMN company_id CASCADE;
ALTER TABLE app.cost_factor DROP COLUMN company_id CASCADE;
ALTER TABLE app.part_unit DROP COLUMN company_id CASCADE;

